// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    L1Block c;
    function setUp() public { c = new L1Block(); }
    function testFuzz_property(address sender) public {
        vm.assume(sender != address(c));
        vm.assume(sender != address(0));
        bool authorized = (sender == c.depositorAccount());
        bool ok;
        vm.prank(sender);
        try c.setL1BlockValues(0,0,0,bytes32(0),0,bytes32(0),0,0) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == authorized);
    }
}
